          rel: T("Es el proceso «Aplicar una Quick Fix» entero: la garantía de que una corrección o se aplica y se revalida, o deja el modelo como estaba.", "It is the whole 'Apply a Quick Fix' process: the guarantee that a correction either applies and revalidates, or leaves the model as it was."),
          rat: { k: "observable", t: T("Rol arquitectónico observable en la implementación: beforeSnapshot + rollback() en el catch de apply(), y las pilas BoundedHistoryStore de 20 entradas.", "Architectural role observable in the implementation: beforeSnapshot + rollback() in apply()'s catch, and the 20-entry BoundedHistoryStore stacks."), src: [] },
