            { n: "context", purpose: T("Construye el contexto de ejecución y valida que la acción se pueda ofrecer.", "Builds the execution context and validates the action may be offered."), when: T("Al inicio de preview y apply.", "At the start of preview and apply."), in: T("modelId, diagnosticId, actionId, request.", "modelId, diagnosticId, actionId, request."), out: T("ExecutionContext con modelo vivo, metamodelo, acción, documento canónico y selfId.", "ExecutionContext with live model, metamodel, action, canonical document and selfId."), decisions: T("Rechaza (NOT_EXECUTABLE) si el diagnóstico no enlaza la acción o la acción está deshabilitada; selfId es el elemento del diagnóstico o, si no hay, la primera raíz. La precondición no se evalúa aquí sino en el ejecutor.", "Rejects (NOT_EXECUTABLE) if the diagnostic does not link the action or the action is disabled; selfId is the diagnostic's element or, if none, the first root. The precondition is not evaluated here but in the executor."), fx: T("Puede lanzar una validación completa si aún no hay informe.", "May trigger a full validation if there is no report yet."), fail: T("NOT_FOUND si la acción o el diagnóstico no existen.", "NOT_FOUND if the action or diagnostic do not exist."), next: T("execute(context).", "execute(context)."), src: [S(VQ + "QuickFixRuntimeService.java", 179)] },
            { n: "rollback", purpose: T("Restaura la instantánea previa tras un fallo.", "Restores the previous snapshot after a failure."), when: T("En el catch de apply, undo y redo.", "In the catch of apply, undo and redo."), in: T("modelId, instantánea, excepción original.", "modelId, snapshot, original exception."), out: T("La excepción original o una de fallo de compensación.", "The original exception or a compensation-failure one."), decisions: T("Si restore falla, suprime ese error en el original y avisa de que no se pudo restaurar.", "If restore fails it suppresses that error into the original and warns it could not restore."), fx: T("Sobrescribe el modelo vivo con la instantánea.", "Overwrites the live model with the snapshot."), fail: T("QuickFixRuntimeException(EXECUTION_FAILED) si no puede restaurar.", "QuickFixRuntimeException(EXECUTION_FAILED) if it cannot restore."), next: T("publishFailed.", "publishFailed."), src: [S(VQ + "QuickFixRuntimeService.java", 252)] }
