          calls: ["qf_grammar_code_action", { n: "GrammarRuleGraphAnalyzer", d: T("Grafo de reglas: recursiones y reescritura.", "Rule graph: recursions and rewrite.") }, { n: "GrammarProperties", d: T("Umbrales automaticFixMinimumScore / Margin.", "Thresholds automaticFixMinimumScore / Margin.") }],
